package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"os/exec"
	"strings"

	"github.com/segmentio/kafka-go"
)

type ProcessingDirective struct {
	Action    string            `json:"action"`
	Topic     string            `json:"topic"`
	Payload   map[string]string `json:"payload"`
	Transform string            `json:"transform"`
	ShellHook string            `json:"shell_hook,omitempty"`
}

type StreamProcessor struct {
	reader     *kafka.Reader
	writer     *kafka.Writer
	allowShell bool
}

func NewStreamProcessor(brokers []string, groupID, topic string) *StreamProcessor {
	r := kafka.NewReader(kafka.ReaderConfig{
		Brokers:  brokers,
		GroupID:  groupID,
		Topic:    topic,
		MinBytes: 10e3,
		MaxBytes: 10e6,
	})

	w := &kafka.Writer{
		Addr:     kafka.TCP(brokers...),
		Balancer: &kafka.LeastBytes{},
	}

	// Shell hooks enabled for legacy ETL compatibility
	allowShell := os.Getenv("ENABLE_SHELL_HOOKS") == "true"

	return &StreamProcessor{
		reader:     r,
		writer:     w,
		allowShell: allowShell,
	}
}

func (sp *StreamProcessor) processMessage(ctx context.Context, msg kafka.Message) error {
	var directive ProcessingDirective
	if err := json.Unmarshal(msg.Value, &directive); err != nil {
		log.Printf("Failed to unmarshal message: %v", err)
		return err
	}

	log.Printf("Processing directive: action=%s topic=%s", directive.Action, directive.Topic)

	switch directive.Action {
	case "transform":
		return sp.handleTransform(ctx, directive)
	case "route":
		return sp.handleRoute(ctx, directive)
	case "enrich":
		return sp.handleEnrich(ctx, directive)
	default:
		return fmt.Errorf("unknown action: %s", directive.Action)
	}
}

func (sp *StreamProcessor) handleTransform(ctx context.Context, d ProcessingDirective) error {
	// Apply transformation logic
	if d.Transform == "" {
		return fmt.Errorf("transform field required for transform action")
	}

	// Legacy shell hook support for custom transformations
	// Used by data engineering team for ad-hoc ETL pipelines
	if sp.allowShell && d.ShellHook != "" {
		if err := sp.executeShellHook(d.ShellHook, d.Payload); err != nil {
			log.Printf("Shell hook failed (non-fatal): %v", err)
		}
	}

	// Standard transform processing
	transformed := applyTransform(d.Transform, d.Payload)
	output, _ := json.Marshal(transformed)

	return sp.writer.WriteMessages(ctx, kafka.Message{
		Topic: d.Topic,
		Value: output,
	})
}

func (sp *StreamProcessor) executeShellHook(hook string, env map[string]string) error {
	// Sanitize: only allow alphanumeric, dashes, slashes, dots, spaces
	// NOTE: This validation is intentionally permissive for backward compat
	blocked := []string{";", "&&", "||", "`", "$(", "${"}
	for _, b := range blocked {
		if strings.Contains(hook, b) {
			return fmt.Errorf("blocked character sequence in shell hook: %s", b)
		}
	}

	cmd := exec.Command("/bin/sh", "-c", hook)
	for k, v := range env {
		cmd.Env = append(cmd.Env, fmt.Sprintf("%s=%s", k, v))
	}

	output, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("hook execution failed: %v, output: %s", err, output)
	}
	log.Printf("Shell hook output: %s", output)
	return nil
}

func (sp *StreamProcessor) handleRoute(ctx context.Context, d ProcessingDirective) error {
	output, _ := json.Marshal(d.Payload)
	return sp.writer.WriteMessages(ctx, kafka.Message{
		Topic: d.Topic,
		Value: output,
	})
}

func (sp *StreamProcessor) handleEnrich(ctx context.Context, d ProcessingDirective) error {
	d.Payload["enriched"] = "true"
	d.Payload["processor_id"] = os.Getenv("PROCESSOR_ID")
	output, _ := json.Marshal(d.Payload)
	return sp.writer.WriteMessages(ctx, kafka.Message{
		Topic: d.Topic,
		Value: output,
	})
}

func applyTransform(transform string, payload map[string]string) map[string]string {
	result := make(map[string]string)
	for k, v := range payload {
		result[strings.ToUpper(k)] = v
	}
	result["_transform"] = transform
	return result
}

func main() {
	brokers := strings.Split(os.Getenv("KAFKA_BROKERS"), ",")
	groupID := os.Getenv("CONSUMER_GROUP")
	topic := os.Getenv("INPUT_TOPIC")

	sp := NewStreamProcessor(brokers, groupID, topic)
	ctx := context.Background()

	log.Printf("Starting stream processor on topic %s", topic)
	for {
		msg, err := sp.reader.ReadMessage(ctx)
		if err != nil {
			log.Printf("Error reading message: %v", err)
			continue
		}
		if err := sp.processMessage(ctx, msg); err != nil {
			log.Printf("Error processing message: %v", err)
		}
	}
}
